import data from "@/lib/family-media.json";

/** One entry of the /family album — generated by scripts/build-family-media.mjs */
export type FamilyItem =
  | { kind: "photo"; src: string; w: number; h: number; date: string | null }
  /** iPhone Live Photo: still + short motion clip */
  | { kind: "live"; src: string; video: string; w: number; h: number; date: string | null }
  | { kind: "video"; src: string; poster: string; w: number; h: number; duration: number; date: string | null };

export const FAMILY_MEDIA = data as FamilyItem[];

export interface MonthGroup {
  key: string;   // "2026-10" or "undated"
  label: string; // "Tháng 10 · 2026"
  year: string | null;
  items: { item: FamilyItem; index: number }[];
}

/** Group (already date-sorted) items by month, keeping each item's index in the list. */
export function groupByMonth(items: FamilyItem[]): MonthGroup[] {
  const groups: MonthGroup[] = [];
  items.forEach((item, index) => {
    const key = item.date ? item.date.slice(0, 7) : "undated";
    let g = groups[groups.length - 1];
    if (!g || g.key !== key) {
      const [y, m] = key.split("-");
      g = {
        key,
        label: key === "undated" ? "Chưa rõ ngày" : `Tháng ${Number(m)} · ${y}`,
        year: key === "undated" ? null : y,
        items: [],
      };
      groups.push(g);
    }
    g.items.push({ item, index });
  });
  return groups;
}

export function formatDate(iso: string | null): string {
  if (!iso) return "";
  const [d] = iso.split("T");
  const [y, m, day] = d.split("-");
  return `${Number(day)} tháng ${Number(m)}, ${y}`;
}

export function formatDuration(s: number): string {
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}
